def setup_logger(name):
    logger = logging.getLogger(name)
    logger.setLevel(logging.INFO)
    logger.handlers.clear()
    handler = logging.StreamHandler()
    handler.setFormatter(logging.Formatter('%(asctime)s | %(levelname)s | %(message)s'))
    logger.addHandler(handler)
    logger.propagate = False
    return logger


def to_numpy(value, dtype=None):
    if value is None:
        return None
    if isinstance(value, torch.Tensor):
        value = value.detach().cpu().numpy()
    else:
        value = np.asarray(value)
    if dtype is not None:
        value = value.astype(dtype, copy=False)
    return value


def inject_gt_names(data_dict, class_names):
    if 'gt_boxes' in data_dict and 'gt_names' not in data_dict:
        boxes = to_numpy(data_dict['gt_boxes'])
        labels = boxes[:, -1].astype(np.int64)
        if np.any(labels < 1) or np.any(labels > len(class_names)):
            raise ValueError(f'Invalid GT labels while reconstructing gt_names: {np.unique(labels)}')
        data_dict['gt_names'] = np.asarray([class_names[label - 1] for label in labels])
    return data_dict


def dataset_file(dataset_dir, segment):
    dataset_dir = Path(dataset_dir)
    candidates = [
        dataset_dir / f'{segment}.pkl',
        dataset_dir / f'{segment}_d.pkl',
    ]
    for path in candidates:
        if path.is_file():
            return path
    raise FileNotFoundError(
        f'No dataset pickle for segment {segment!r}; tried: '
        + ', '.join(str(path) for path in candidates)
    )


def annotation_file(annos_dir, segment):
    path = Path(annos_dir) / f'{segment}_a.pkl'
    if not path.is_file():
        raise FileNotFoundError(path)
    return path


def discover_selected_segments(dataset_dir, annos_dir):
    anno_paths = sorted(Path(annos_dir).glob('*_a.pkl'))
    if not anno_paths:
        raise RuntimeError(f'No *_a.pkl files found in {annos_dir}')
    segments = [path.stem[:-2] for path in anno_paths]
    for segment in segments:
        dataset_file(dataset_dir, segment)
    return segments


def segment_name_from_info(info):
    return str(info['point_cloud']['lidar_sequence'])


def filter_dataset_to_generated_segments(dataset, selected_segments):
    selected = set(selected_segments)
    original_infos = list(dataset.infos)
    dataset.infos = [
        info for info in original_infos
        if segment_name_from_info(info) in selected
    ]
    present = {segment_name_from_info(info) for info in dataset.infos}
    missing = selected - present
    if missing:
        raise RuntimeError(
            'Generated segments are absent from the detector dataset infos: '
            + ', '.join(sorted(missing))
        )
    if not dataset.infos:
        raise RuntimeError('Filtering left zero evaluation frames')
    return original_infos


def make_loader(dataset, workers):
    return DataLoader(
        dataset,
        batch_size=1,
        shuffle=False,
        num_workers=workers,
        pin_memory=True,
        drop_last=False,
        collate_fn=dataset.collate_batch,
    )


def build_index_maps(dataset):
    global_to_segment = {}
    counts = {}
    pose_map = {}
    ordered_segments = []
    seen = set()
    for global_idx, info in enumerate(dataset.infos):
        segment = segment_name_from_info(info)
        local_idx = counts.get(segment, 0)
        counts[segment] = local_idx + 1
        global_to_segment[global_idx] = (segment, local_idx)
        if 'pose' in info:
            pose_map[(segment, local_idx)] = np.asarray(info['pose']).reshape(4, 4)
        if segment not in seen:
            ordered_segments.append(segment)
            seen.add(segment)
    return global_to_segment, counts, pose_map, ordered_segments


def build_cp_index(cp_dataset):
    index = {}
    counts = {}
    for global_idx, info in enumerate(cp_dataset.infos):
        segment = segment_name_from_info(info)
        local_idx = counts.get(segment, 0)
        counts[segment] = local_idx + 1
        index[(segment, local_idx)] = global_idx
    return index, counts


def atomic_pickle_dump(value, path):
    path = Path(path)
    path.parent.mkdir(parents=True, exist_ok=True)
    temp = path.with_suffix(path.suffix + '.tmp')
    with open(temp, 'wb') as handle:
        pkl.dump(value, handle)
    os.replace(temp, path)


def json_default(value):
    if isinstance(value, np.generic):
        return value.item()
    if isinstance(value, np.ndarray):
        return value.tolist()
    if isinstance(value, torch.Tensor):
        return value.detach().cpu().tolist()
    raise TypeError(f'Not JSON serializable: {type(value).__name__}')


def atomic_json_dump(value, path):
    path = Path(path)
    path.parent.mkdir(parents=True, exist_ok=True)
    temp = path.with_suffix(path.suffix + '.tmp')
    with open(temp, 'w', encoding='utf-8') as handle:
        json.dump(value, handle, indent=2, sort_keys=True, default=json_default)
    os.replace(temp, path)


def validate_completed_segments(pred_dir, ordered_segments, counts):
    completed = set()
    pred_dir = Path(pred_dir)
    for segment in ordered_segments:
        path = pred_dir / f'{segment}_p.pkl'
        if not path.is_file():
            continue
        try:
            with open(path, 'rb') as handle:
                preds = pkl.load(handle)
            if len(preds) != counts[segment]:
                continue
            if any(str(pred.get('frame_id')) == 'None' for pred in preds):
                continue
            completed.add(segment)
        except Exception:
            continue
    return completed


def load_all_predictions(pred_dir, ordered_segments, counts):
    all_preds = {}
    for segment in ordered_segments:
        path = Path(pred_dir) / f'{segment}_p.pkl'
        if not path.is_file():
            raise FileNotFoundError(f'Missing prediction file: {path}')
        with open(path, 'rb') as handle:
            preds = pkl.load(handle)
        if len(preds) != counts[segment]:
            raise RuntimeError(
                f'Prediction count mismatch for {segment}: '
                f'{len(preds)} != {counts[segment]}'
            )
        all_preds[segment] = preds
    return all_preds


def assemble_det_annos(dataset, segment_predictions):
    counters = {}
    det_annos = []
    for info in dataset.infos:
        segment = segment_name_from_info(info)
        local_idx = counters.get(segment, 0)
        prediction = segment_predictions[segment][local_idx]
        if str(prediction['frame_id']) != str(info['frame_id']):
            raise AssertionError(
                f'Frame mismatch at {segment}[{local_idx}]: '
                f"pred={prediction['frame_id']} info={info['frame_id']}"
            )
        det_annos.append(prediction)
        counters[segment] = local_idx + 1
    return det_annos


def frame_is_modified(segment_data, local_idx):
    """True when this frame's stored cloud differs from the clean cloud.
    Gates the CP4F fast path (rebuild is always exact). Injection datasets
    mark attacked frames with spoof_gt / modified_this_frame."""
    frame = segment_data[local_idx]
    if 'modified_this_frame' in frame:
        return bool(frame['modified_this_frame'])
    return frame.get('spoof_gt') is not None


def scale_proposal_velocity(boxes):
    """Eq. 9: convert raw CP4F velocities to the backward motion MSF/PTT use."""
    boxes = np.asarray(boxes, dtype=np.float32).copy()
    if boxes.shape[0] and boxes.shape[1] >= 9:
        boxes[:, 7:9] = -0.1 * boxes[:, 7:9]
    return boxes


class CP4FProposalProvider:
    """Computes (and caches) per-frame CenterPoint-4f proposals on demand.
    Identical to the removal / MSF-injection provider; see those scripts for
    the process_4frames semantics. Persists per segment so MSF-4/MSF-8/PTT
    share one computation via the run's cp4f_proposals/ dir."""

    def __init__(self, cp_dataset, cp_model, cp_index, pose_map,
                 cache_dir, expected_counts, logger):
        self.cp_dataset = cp_dataset
        self.cp_model = cp_model
        self.cp_index = cp_index
        self.pose_map = pose_map
        self.cache_dir = Path(cache_dir) if cache_dir else None
        self.expected_counts = expected_counts
        self.logger = logger
        self.cache = {}
        self.segment = None
        self.dirty = False
        self.stats = {'fast_path': 0, 'rebuilt': 0, 'loaded_from_disk': 0}

    def _cache_path(self, segment):
        return self.cache_dir / f'{segment}_cp4f.pkl'

    def start_segment(self, segment):
        self.segment = segment
        self.cache = {}
        self.dirty = False
        if self.cache_dir is None:
            return
        path = self._cache_path(segment)
        if not path.is_file():
            return
        try:
            with open(path, 'rb') as handle:
                stored = pkl.load(handle)
            for local_idx, record in stored.items():
                self.cache[(segment, int(local_idx))] = (
                    np.asarray(record['pred_boxes'], dtype=np.float32),
                    np.asarray(record['pred_scores'], dtype=np.float32),
                    np.asarray(record['pred_labels'], dtype=np.int64),
                )
            self.stats['loaded_from_disk'] += len(stored)
            self.logger.info(
                'Loaded %d cached CP4F proposals for %s', len(stored), segment
            )
        except Exception:
            self.cache = {}

    def end_segment(self):
        if not (self.cache_dir and self.segment and self.dirty):
            return
        entries = {
            local_idx: {
                'pred_boxes': boxes,
                'pred_scores': scores,
                'pred_labels': labels,
            }
            for (seg, local_idx), (boxes, scores, labels) in self.cache.items()
            if seg == self.segment
        }
        expected = self.expected_counts.get(self.segment)
        if expected is not None and len(entries) != expected:
            return  # only persist complete segments (atomic contract)
        atomic_pickle_dump(entries, self._cache_path(self.segment))
        self.logger.info(
            'Persisted %d CP4F proposals for %s', len(entries), self.segment
        )
        self.dirty = False

    def get(self, segment, local_idx, segment_data):
        key = (segment, local_idx)
        if key in self.cache:
            return self.cache[key]
        if getattr(self, 'strict', False):
            raise RuntimeError(
                f'CP4F proposal cache miss for {segment}[{local_idx}]; refusing to '
                'recompute CP4F with the PTT pcdet fork.'
            )

        lag_indices = [max(local_idx - lag, 0) for lag in range(4)]
        any_modified = any(
            frame_is_modified(segment_data, idx) for idx in lag_indices
        )
        cp_global = self.cp_index[(segment, local_idx)]

        if not any_modified:
            data_dict = self.cp_dataset[cp_global]
            self.stats['fast_path'] += 1
        else:
            pose_cur = self.pose_map[(segment, local_idx)]
            pose_cur_inv = np.linalg.inv(pose_cur)
            merged = []
            for lag_idx in lag_indices:
                points = to_numpy(
                    segment_data[lag_idx]['points'], np.float32
                ).copy()
                points[:, -1] = (local_idx - lag_idx) * 0.1
                pose_lag = self.pose_map[(segment, lag_idx)]
                ones = np.ones((points.shape[0], 1), dtype=points.dtype)
                hom = np.hstack((points[:, :3], ones))
                xyz_current = hom @ pose_lag.T @ pose_cur_inv.T
                merged.append(
                    np.hstack((xyz_current[:, :3], points[:, 3:]))
                )
            aggregated = np.vstack(merged).astype(np.float32, copy=False)
            data_dict = self.cp_dataset[cp_global].copy()
            for k in ('voxels', 'voxel_coords', 'voxel_num_points'):
                data_dict.pop(k, None)
            data_dict['points'] = aggregated
            data_dict = inject_gt_names(data_dict, self.cp_dataset.class_names)
            data_dict = self.cp_dataset.prepare_data(data_dict)
            self.stats['rebuilt'] += 1

        batch = self.cp_dataset.collate_batch([data_dict])
        load_data_to_gpu(batch)
        with torch.no_grad():
            pred_dicts, _ = self.cp_model(batch)
        boxes = to_numpy(pred_dicts[0]['pred_boxes'], np.float32)
        scores = to_numpy(pred_dicts[0]['pred_scores'], np.float32)
        labels = to_numpy(pred_dicts[0]['pred_labels'], np.int64)
        result = (boxes, scores, labels)
        self.cache[key] = result
        self.dirty = True
        return result


def prediction_arrays(frame_pred):
    boxes = frame_pred.get('boxes_lidar', frame_pred.get('pred_boxes'))
    labels = frame_pred.get('pred_labels')
    scores = frame_pred.get('score', frame_pred.get('pred_scores'))
    boxes = to_numpy(boxes, np.float32)
    labels = to_numpy(labels, np.int64)
    scores = to_numpy(scores, np.float32)
    if boxes is None:
        boxes = np.empty((0, 7), dtype=np.float32)
    if labels is None:
        labels = np.empty((0,), dtype=np.int64)
    if scores is None:
        scores = np.empty((0,), dtype=np.float32)
    return boxes, labels, scores


def spoof_false_positive(frame_pred, spoof_box):
    """Paper semantics: argmax-IoU3D prediction (any class) vs spoof box,
    classified by its label: vehicle FP at IoU >= 0.7, ped/cyc at 0.5.
    Returns None when there are no predictions at all."""
    pred_boxes, pred_labels, pred_scores = prediction_arrays(frame_pred)
    if len(pred_boxes) == 0:
        return None
    spoof = to_numpy(spoof_box, np.float32).reshape(-1)[:7]
    pred_tensor = torch.as_tensor(pred_boxes[:, :7], dtype=torch.float32, device='cuda')
    gt_tensor = torch.as_tensor(spoof, dtype=torch.float32, device='cuda').unsqueeze(0)
    ious = iou3d_nms_utils.boxes_iou3d_gpu(pred_tensor, gt_tensor)[:, 0]
    best_idx = int(torch.argmax(ious).item())
    max_iou = float(ious[best_idx].item())
    label = int(pred_labels[best_idx])
    score = float(pred_scores[best_idx])
    if label == 1:
        is_fp = max_iou >= 0.7
    elif label in (2, 3):
        is_fp = max_iou >= 0.5
    else:
        is_fp = False
    return {
        'max_iou': max_iou,
        'label': label,
        'score': score,
        'is_fp': bool(is_fp),
    }


def segment_asr_statistics(values):
    """Macro statistics over per-segment ASRs.

    Only segments containing at least one spoof-target frame are included.
    Each segment therefore contributes one equally weighted ASR value,
    independent of how many spoof-target frames that segment contains.
    """
    values = np.asarray(values, dtype=np.float64)
    values = values[np.isfinite(values)]
    if values.size == 0:
        return {
            'count': 0,
            'mean': None,
            'min': None,
            'median': None,
            'max': None,
        }
    return {
        'count': int(values.size),
        'mean': float(np.mean(values)),
        'min': float(np.min(values)),
        'median': float(np.median(values)),
        'max': float(np.max(values)),
    }


def calculate_injection_metrics(dataset, dataset_dir, segment_predictions):
    counters = {}
    cached_segment = None
    segment_data = None

    total = 0
    zero_prediction_frames = 0
    fp_counts = {1: 0, 2: 0, 3: 0}
    fp_scores = {1: [], 2: [], 3: []}
    best_ious = []
    fp_records = []

    # Per-segment counters use the same denominator and FP definition as the
    # existing dataset-level ASRs. A zero-prediction target frame remains in
    # the denominator and contributes no false positive.
    segment_counts = {}

    for info in dataset.infos:
        segment = segment_name_from_info(info)
        local_idx = counters.get(segment, 0)
        counters[segment] = local_idx + 1

        if segment != cached_segment:
            with open(dataset_file(dataset_dir, segment), 'rb') as handle:
                segment_data = pkl.load(handle)
            cached_segment = segment

        frame = segment_data[local_idx]
        if str(frame['frame_id']) != str(info['frame_id']):
            raise AssertionError(
                f"Dataset frame mismatch: {frame['frame_id']} != {info['frame_id']}"
            )
        spoof_box = frame.get('spoof_gt')
        if spoof_box is None:
            continue

        total += 1
        segment_count = segment_counts.setdefault(segment, {
            'n_target_frames': 0,
            'n_vehicle_fp': 0,
            'n_pedestrian_fp': 0,
            'n_cyclist_fp': 0,
            'n_zero_prediction_frames': 0,
        })
        segment_count['n_target_frames'] += 1

        frame_pred = segment_predictions[segment][local_idx]
        outcome = spoof_false_positive(frame_pred, spoof_box)
        if outcome is None:
            zero_prediction_frames += 1
            segment_count['n_zero_prediction_frames'] += 1
            continue
        best_ious.append(outcome['max_iou'])
        if outcome['is_fp']:
            fp_counts[outcome['label']] += 1
            if outcome['label'] == 1:
                segment_count['n_vehicle_fp'] += 1
            elif outcome['label'] == 2:
                segment_count['n_pedestrian_fp'] += 1
            elif outcome['label'] == 3:
                segment_count['n_cyclist_fp'] += 1
            fp_scores[outcome['label']].append(outcome['score'])
            fp_records.append({
                'segment': segment,
                'local_idx': int(local_idx),
                'frame_id': str(info['frame_id']),
                'label': outcome['label'],
                'score': outcome['score'],
                'iou': outcome['max_iou'],
                'spoof_kept_count': int(frame.get(
                    'spoof_kept_count', frame.get('n_spoof_k', 0)
                ) or 0),
            })

    segment_metrics = {}
    for segment in sorted(segment_counts):
        counts = segment_counts[segment]
        denominator = counts['n_target_frames']
        if denominator <= 0:
            continue
        segment_metrics[segment] = {
            **counts,
            'asr': float(counts['n_vehicle_fp'] / denominator),
            'asr_pedestrian': float(counts['n_pedestrian_fp'] / denominator),
            'asr_cyclist': float(counts['n_cyclist_fp'] / denominator),
            'zero_prediction_frame_rate': float(
                counts['n_zero_prediction_frames'] / denominator
            ),
        }

    segment_asr_summary = {
        'vehicle': segment_asr_statistics([
            values['asr'] for values in segment_metrics.values()
        ]),
        'pedestrian': segment_asr_statistics([
            values['asr_pedestrian'] for values in segment_metrics.values()
        ]),
        'cyclist': segment_asr_statistics([
            values['asr_cyclist'] for values in segment_metrics.values()
        ]),
    }

    asr = None if total == 0 else float(fp_counts[1] / total)
    zero_pred_rate = None if total == 0 else float(zero_prediction_frames / total)
    return {
        'asr': asr,
        'asr_pedestrian': None if total == 0 else float(fp_counts[2] / total),
        'asr_cyclist': None if total == 0 else float(fp_counts[3] / total),
        'n_target_frames': int(total),
        'n_vehicle_fp': int(fp_counts[1]),
        'n_pedestrian_fp': int(fp_counts[2]),
        'n_cyclist_fp': int(fp_counts[3]),
        'zero_prediction_frame_rate': zero_pred_rate,
        'n_segments_with_target_frames': int(len(segment_metrics)),
        'segment_metrics': segment_metrics,
        'segment_asr_summary': segment_asr_summary,
        'fp_score_stats': score_statistics(fp_scores[1]),
        'spoof_best_iou_stats': score_statistics(best_ious),
        'fp_scores_vehicle': np.asarray(fp_scores[1], dtype=np.float32),
        'fp_scores_pedestrian': np.asarray(fp_scores[2], dtype=np.float32),
        'fp_scores_cyclist': np.asarray(fp_scores[3], dtype=np.float32),
        'spoof_best_ious': np.asarray(best_ious, dtype=np.float32),
        'fp_records': fp_records,
    }


def score_statistics(scores):
    values = np.asarray(scores, dtype=np.float64)
    if values.size == 0:
        return {
            'count': 0,
            'mean': None,
            'std': None,
            'min': None,
            'q25': None,
            'median': None,
            'q75': None,
            'max': None,
        }
    return {
        'count': int(values.size),
        'mean': float(np.mean(values)),
        'std': float(np.std(values, ddof=0)),
        'min': float(np.min(values)),
        'q25': float(np.quantile(values, 0.25)),
        'median': float(np.median(values)),
        'q75': float(np.quantile(values, 0.75)),
        'max': float(np.max(values)),
    }


def compute_l2_map_maph(result_dict, class_names):
    class_metrics = {}
    aps = []
    aphs = []
    aliases = {
        'VEHICLE': 'VEHICLE',
        'PEDESTRIAN': 'PEDESTRIAN',
        'CYCLIST': 'CYCLIST',
    }
    for class_name in class_names:
        canonical = aliases.get(str(class_name).upper())
        if canonical is None:
            continue
        ap_key = f'OBJECT_TYPE_TYPE_{canonical}_LEVEL_2/AP'
        aph_key = f'OBJECT_TYPE_TYPE_{canonical}_LEVEL_2/APH'
        ap = result_dict.get(ap_key)
        aph = result_dict.get(aph_key)
        class_metrics[class_name] = {
            'ap_key': ap_key,
            'aph_key': aph_key,
            'ap': None if ap is None else float(ap),
            'aph': None if aph is None else float(aph),
        }
        if ap is not None and np.isfinite(float(ap)):
            aps.append(float(ap))
        if aph is not None and np.isfinite(float(aph)):
            aphs.append(float(aph))
    expected = len(class_metrics)
    if len(aps) != expected or len(aphs) != expected:
        missing = [
            values for values in class_metrics.values()
            if values['ap'] is None or values['aph'] is None
        ]
        raise KeyError(
            'Could not calculate L2 mAP/mAPH from result_dict. Missing metrics: '
            + json.dumps(missing, indent=2)
        )
    return {
        'per_class': class_metrics,
        'l2_map': float(np.mean(aps)),
        'l2_maph': float(np.mean(aphs)),
        'classes_averaged': list(class_metrics.keys()),
    }


def print_injection_summary(target_metrics):
    print('\n===== SPOOF FALSE-POSITIVE METRICS (INJECTION) =====')
    asr = target_metrics['asr']
    print(f"ASR (vehicle FP rate): {asr:.6f} ({100.0 * asr:.2f}%)"
          if asr is not None else 'ASR: N/A')
    print(f"Target (spoofed) frames: {target_metrics['n_target_frames']}")
    print(f"Vehicle FPs (IoU>=0.7): {target_metrics['n_vehicle_fp']}")
    print(f"Pedestrian FPs (IoU>=0.5): {target_metrics['n_pedestrian_fp']}")
    print(f"Cyclist FPs (IoU>=0.5): {target_metrics['n_cyclist_fp']}")
    print(f"Zero-prediction frame rate: {target_metrics['zero_prediction_frame_rate']}")


    print('\n===== PER-SEGMENT ASR SUMMARY (MACRO OVER SEGMENTS) =====')
    print(
        'Segments with at least one spoof-target frame: '
        f"{target_metrics['n_segments_with_target_frames']}"
    )
    for display_name, key in (
        ('Vehicle', 'vehicle'),
        ('Pedestrian', 'pedestrian'),
        ('Cyclist', 'cyclist'),
    ):
        stats = target_metrics['segment_asr_summary'][key]
        if stats['count'] == 0:
            print(f'{display_name}: N/A')
            continue
        print(
            f"{display_name}: n={stats['count']}, "
            f"mean={stats['mean']:.6f} ({100.0 * stats['mean']:.2f}%), "
            f"min={stats['min']:.6f} ({100.0 * stats['min']:.2f}%), "
            f"median={stats['median']:.6f} ({100.0 * stats['median']:.2f}%), "
            f"max={stats['max']:.6f} ({100.0 * stats['max']:.2f}%)"
        )

    stats = target_metrics['fp_score_stats']
    print('\n===== VEHICLE FP SCORE DISTRIBUTION =====')
    print(f"N: {stats['count']}")
    for key in ('mean', 'std', 'min', 'q25', 'median', 'q75', 'max'):
        value = stats[key]
        print(f'{key}: N/A' if value is None else f'{key}: {value:.6f}')

    iou_stats = target_metrics['spoof_best_iou_stats']
    print('\n===== BEST IoU AT SPOOF LOCATION (all target frames) =====')
    print(f"N: {iou_stats['count']}")
    for key in ('mean', 'median', 'max'):
        value = iou_stats[key]
        print(f'{key}: N/A' if value is None else f'{key}: {value:.6f}')


def print_l2_summary(l2_summary):
    print('\n===== WAYMO LEVEL-2 SUMMARY =====')
    for class_name, values in l2_summary['per_class'].items():
        print(
            f"{class_name}: L2 AP={values['ap']:.6f} "
            f"({100.0 * values['ap']:.2f}%), "
            f"L2 APH={values['aph']:.6f} ({100.0 * values['aph']:.2f}%)"
        )
    print(
        f"L2 mAP: {l2_summary['l2_map']:.6f} "
        f"({100.0 * l2_summary['l2_map']:.2f}%)"
    )
    print(
        f"L2 mAPH: {l2_summary['l2_maph']:.6f} "
        f"({100.0 * l2_summary['l2_maph']:.2f}%)"
    )


# ---------------------------------------------------------------------------
# Proposal-cache seeding from stored CP4F ATLAS predictions + live verification
# ---------------------------------------------------------------------------
def seed_proposal_cache(seed_pred_dir, cache_dir, dataset_dir, ordered_segments,
                        counts, logger):
    """Convert cp4f_atlas/<label>/predictions/{segment}_p.pkl into the
    {segment}_cp4f.pkl cache format consumed by CP4FProposalProvider. Every
    entry is keyed by its position in dataset/{segment}.pkl after asserting the
    prediction's frame_id equals that dataset frame's frame_id."""
    import gc
    cache_dir = Path(cache_dir)
    cache_dir.mkdir(parents=True, exist_ok=True)
    seeded = skipped = 0
    for segment in ordered_segments:
        out = cache_dir / f'{segment}_cp4f.pkl'
        if out.is_file():
            skipped += 1
            continue
        with open(dataset_file(dataset_dir, segment), 'rb') as handle:
            segment_data = pkl.load(handle)
        frame_ids = [str(frame['frame_id']) for frame in segment_data]
        del segment_data
        gc.collect()
        pred_path = Path(seed_pred_dir) / f'{segment}_p.pkl'
        with open(pred_path, 'rb') as handle:
            preds = pkl.load(handle)
        if len(preds) != len(frame_ids) or len(frame_ids) != counts[segment]:
            raise RuntimeError(
                f'Seed length mismatch for {segment}: preds={len(preds)} '
                f'dataset={len(frame_ids)} expected={counts[segment]}'
            )
        by_id = {}
        for pred in preds:
            fid = str(pred['frame_id'])
            if fid in by_id:
                raise RuntimeError(f'Duplicate frame_id {fid} in {pred_path}')
            by_id[fid] = pred
        entries = {}
        for local_idx, fid in enumerate(frame_ids):
            if fid not in by_id:
                raise RuntimeError(f'frame_id {fid} missing from {pred_path}')
            pred = by_id[fid]
            entries[local_idx] = {
                'pred_boxes': np.asarray(pred['boxes_lidar'], dtype=np.float32),
                'pred_scores': np.asarray(pred['score'], dtype=np.float32),
                'pred_labels': np.asarray(pred['pred_labels'], dtype=np.int64),
            }
        atomic_pickle_dump(entries, out)
        seeded += 1
    logger.info('Proposal cache seeding: %d segments seeded from %s, %d already present',
                seeded, seed_pred_dir, skipped)


def verify_seeded_against_fullval(cache_dir, fullval_pkl, dataset_dir,
                                  ordered_segments, n_segments, logger):
    """Sanity-check the seeded cache against OpenPCDet's own CP4F output on the
    clean full val set (same checkpoint). On a frame whose whole 4-frame window
    is unmodified, the ATLAS cloud equals the original cloud, so the proposals
    must agree up to GPU nondeterminism. Catches a GT/no-GT swap or a cache
    produced by different code/config. CPU only."""
    import gc
    if not fullval_pkl or n_segments <= 0:
        logger.warning('Full-val proposal check DISABLED')
        return
    picks = np.linspace(0, len(ordered_segments) - 1,
                        num=min(n_segments, len(ordered_segments)))
    segments = [ordered_segments[int(round(i))] for i in picks]
    with open(fullval_pkl, 'rb') as handle:
        fullval = pkl.load(handle)
    ref = {str(d['frame_id']): np.sort(np.asarray(d['score'], np.float32))[::-1]
           for d in fullval if any(seg in str(d['frame_id']) for seg in segments)}
    del fullval
    gc.collect()
    checked = failed = 0
    for segment in segments:
        with open(dataset_file(dataset_dir, segment), 'rb') as handle:
            segment_data = pkl.load(handle)
        meta = [(str(f['frame_id']), frame_is_modified(segment_data, i))
                for i, f in enumerate(segment_data)]
        del segment_data
        gc.collect()
        with open(Path(cache_dir) / f'{segment}_cp4f.pkl', 'rb') as handle:
            cache = pkl.load(handle)
        clean = [i for i, (fid, _) in enumerate(meta)
                 if fid in ref and not any(meta[max(i - lag, 0)][1] for lag in range(4))]
        for i in clean[::max(1, len(clean) // 5)][:5]:
            mine = np.sort(cache[i]['pred_scores'])[::-1]
            theirs = ref[meta[i][0]]
            k = min(20, len(mine), len(theirs))
            count_ok = abs(len(mine) - len(theirs)) <= max(3, int(0.08 * len(theirs)))
            score_gap = float(np.median(np.abs(mine[:k] - theirs[:k]))) if k else 0.0
            checked += 1
            if not count_ok or score_gap > 0.01:
                failed += 1
                logger.error('FULLVAL MISMATCH %s[%d]: n=%d vs %d, median|dscore| top%d=%.4f',
                             segment, i, len(mine), len(theirs), k, score_gap)
            else:
                logger.info('fullval ok %s[%d]: n=%d vs %d, median|dscore|=%.4f',
                            segment, i, len(mine), len(theirs), score_gap)
    if checked == 0:
        raise RuntimeError('Full-val check found no clean frames to compare.')
    if failed:
        raise RuntimeError(f'Seeded CP4F proposals disagree with {fullval_pkl} on '
                           f'{failed}/{checked} clean frames. Refusing to evaluate.')
    logger.info('Full-val proposal check PASSED on %d clean frames', checked)


def compute_recall_summary(segment_predictions, thresholds):
    """Same definition as tools/eval_utils: sum per-frame roi/rcnn hit counts
    over all frames, divide by the total number of GT boxes. roi = CP4F
    proposals (current frame) before PTT, rcnn = PTT final boxes."""
    totals = {'gt': 0.0}
    for t in thresholds:
        totals[f'roi_{t}'] = 0.0
        totals[f'rcnn_{t}'] = 0.0
    frames_with_counts = 0
    for preds in segment_predictions.values():
        for frame in preds:
            rc = frame.get('recall_counts')
            if not rc:
                continue
            frames_with_counts += 1
            for k in totals:
                totals[k] += float(rc.get(k, 0.0))
    gt = max(totals['gt'], 1.0)
    out = {'gt_num': int(totals['gt']), 'frames_with_recall': frames_with_counts}
    for t in thresholds:
        out[f'recall_roi_{t}'] = totals[f'roi_{t}'] / gt
        out[f'recall_rcnn_{t}'] = totals[f'rcnn_{t}'] / gt
    return out


def main():
    args = parse_args()
    logger = setup_logger('eval_injection_ptt')
    Path(args.pred_dir).mkdir(parents=True, exist_ok=True)

    # ---- detector (PTT) dataset + model ----
    cfg_from_yaml_file(args.cfg_file, cfg)
    if args.data_path:
        cfg.DATA_CONFIG.DATA_PATH = args.data_path
    cfg.TAG = Path(args.cfg_file).stem
    cfg.EXP_GROUP_PATH = 'atlas_injection_ptt'
    detector_class_names = list(cfg.CLASS_NAMES)
    eval_metric = cfg.MODEL.POST_PROCESSING.EVAL_METRIC
    cfg_recall_thresh = list(cfg.MODEL.POST_PROCESSING.RECALL_THRESH_LIST)

    dataset, _, _ = build_dataloader(
        dataset_cfg=cfg.DATA_CONFIG,
        class_names=cfg.CLASS_NAMES,
        batch_size=1,
        dist=False,
        workers=args.workers,
        logger=logger,
        training=False,
    )
    selected_segments = discover_selected_segments(args.dataset, args.annos_dir)
    filter_dataset_to_generated_segments(dataset, selected_segments)
    loader = make_loader(dataset, args.workers)
    global_to_segment, counts, pose_map, ordered_segments = build_index_maps(dataset)
    logger.info(
        'Evaluating %d frames across %d generated segments with %d-frame PTT',
        len(dataset), len(ordered_segments), args.history,
    )

    model = build_network(cfg.MODEL, num_class=len(cfg.CLASS_NAMES), dataset=dataset)
    model.load_params_from_file(args.ckpt, logger=logger, to_cpu=False)
    model.cuda().eval()

    # ---- CenterPoint-4f (RPN) dataset + model, same pcdet, second cfg ----
    cfg.clear()
    cfg_from_yaml_file(args.cp_cfg, cfg)
    if args.data_path:
        cfg.DATA_CONFIG.DATA_PATH = args.data_path
    cp_dataset, _, _ = build_dataloader(
        dataset_cfg=cfg.DATA_CONFIG,
        class_names=cfg.CLASS_NAMES,
        batch_size=1,
        dist=False,
        workers=args.workers,
        logger=logger,
        training=False,
    )
    filter_dataset_to_generated_segments(cp_dataset, selected_segments)
    cp_model = build_network(cfg.MODEL, num_class=len(cfg.CLASS_NAMES), dataset=cp_dataset)
    cp_model.load_params_from_file(args.cp_ckpt, logger=logger, to_cpu=False)
    cp_model.cuda().eval()
    cp_index, cp_counts = build_cp_index(cp_dataset)
    if cp_counts != counts:
        raise RuntimeError(
            'CP4F dataset frame counts do not match detector dataset counts: '
            f'{sorted(set(cp_counts.items()) ^ set(counts.items()))[:5]}'
        )
    proposals = CP4FProposalProvider(
        cp_dataset=cp_dataset,
        cp_model=cp_model,
        cp_index=cp_index,
        pose_map=pose_map,
        cache_dir=args.proposal_cache_dir or None,
        expected_counts=counts,
        logger=logger,
    )

    if args.seed_pred_dir:
        seed_proposal_cache(
            args.seed_pred_dir, args.proposal_cache_dir, args.dataset,
            ordered_segments, counts, logger,
        )
        verify_seeded_against_fullval(
            args.proposal_cache_dir, args.fullval_pkl, args.dataset,
            ordered_segments, args.verify_segments, logger,
        )
        # Never compute CP4F through this (PTT) pcdet: a cache miss is fatal.
        proposals.strict = True

    completed = validate_completed_segments(args.pred_dir, ordered_segments, counts) if args.resume else set()
    logger.info('Resume: %d complete segment prediction files found', len(completed))

    current_segment = None
    current_preds = None
    segment_data = None

    def flush_current():
        nonlocal current_segment, current_preds
        proposals.end_segment()
        if current_segment is None or current_preds is None:
            return
        if len(current_preds) != counts[current_segment]:
            raise RuntimeError(
                f'Incomplete segment {current_segment}: '
                f'{len(current_preds)} != {counts[current_segment]}'
            )
        atomic_pickle_dump(current_preds, Path(args.pred_dir) / f'{current_segment}_p.pkl')
        logger.info('Saved predictions: %s', current_segment)

    for global_idx, batch in enumerate(tqdm(loader, desc=f'PTT-{args.history} inference')):
        segment, local_idx = global_to_segment[global_idx]
        if segment != current_segment:
            flush_current()
            current_segment = segment
            if segment in completed:
                current_preds = None
                segment_data = None
            else:
                with open(dataset_file(args.dataset, segment), 'rb') as handle:
                    segment_data = pkl.load(handle)
                if len(segment_data) != counts[segment]:
                    raise RuntimeError(f'Dataset length mismatch for {segment}')
                proposals.start_segment(segment)
                current_preds = []

        if current_preds is None:
            continue
        frame = segment_data[local_idx]
        if str(batch['frame_id'][0]) != str(frame['frame_id']):
            raise AssertionError(f"{batch['frame_id'][0]} != {frame['frame_id']}")

        # Proposal history, lag-ascending: FIRST element is the CURRENT
        # frame's proposal, followed by t-1, t-2, ... (clamped at segment
        # start). Each proposal is CP4F-computed on the fly (cached), then
        # velocity-rescaled (Eq. 9) and — for historical frames —
        # transformed into the current frame's ego coordinates (Eq. 10).
        history_indices = [max(local_idx - lag, 0) for lag in range(args.history)]
        pose_cur = pose_map[(segment, local_idx)]

        transformed_boxes = []
        history_scores = []
        history_labels = []
        for historical_idx in history_indices:
            raw_boxes, raw_scores, raw_labels = proposals.get(
                segment, historical_idx, segment_data
            )
            boxes = scale_proposal_velocity(raw_boxes)
            pose_pre = pose_map[(segment, historical_idx)]
            if boxes.shape[0] > 0 and historical_idx != local_idx:
                boxes = dataset.transform_prebox_to_current(boxes, pose_pre, pose_cur)
            transformed_boxes.append(boxes)
            history_scores.append(raw_scores.astype(np.float32, copy=False))
            history_labels.append(raw_labels.astype(np.float32, copy=False))

        max_preds = max((boxes.shape[0] for boxes in transformed_boxes), default=0)
        max_preds = max(max_preds, 1)
        box_dim = max((boxes.shape[1] for boxes in transformed_boxes if boxes.ndim == 2), default=9)

        past_boxes = []
        past_scores = []
        past_labels = []
        for boxes, scores, labels in zip(transformed_boxes, history_scores, history_labels):
            if boxes.shape[1] != box_dim:
                raise RuntimeError(f'Inconsistent proposal box dimensions: {boxes.shape[1]} vs {box_dim}')
            pad = max_preds - boxes.shape[0]
            past_boxes.append(np.pad(boxes, ((0, pad), (0, 0)), mode='constant'))
            past_scores.append(np.pad(scores, (0, pad), mode='constant'))
            past_labels.append(np.pad(labels, (0, pad), mode='constant'))

        past_boxes = np.stack(past_boxes, axis=0).astype(np.float32)
        past_scores = np.stack(past_scores, axis=0).astype(np.float32)
        past_labels = np.stack(past_labels, axis=0).astype(np.float32)

        data_dict = dataset[global_idx].copy()
        for key in ('voxels', 'voxel_coords', 'voxel_num_points'):
            data_dict.pop(key, None)
        data_dict['roi_boxes'] = past_boxes
        data_dict['roi_scores'] = past_scores
        data_dict['roi_labels'] = past_labels
        data_dict['points'] = to_numpy(frame['points'], np.float32)
        data_dict = inject_gt_names(data_dict, dataset.class_names)
        data_dict = dataset.prepare_data(data_dict)
        batch_mod = dataset.collate_batch([data_dict])
        load_data_to_gpu(batch_mod)
        with torch.no_grad():
            pred_dicts, recall_dicts = model(batch_mod)
        annos = dataset.generate_prediction_dicts(batch_mod, pred_dicts, detector_class_names)
        # Per-frame recall counts (as in tools/eval_utils): stored with the
        # predictions so resumed segments still contribute.
        annos[0]['recall_counts'] = {
            k: float(v.item() if hasattr(v, 'item') else v)
            for k, v in (recall_dicts or {}).items()
        }
        current_preds.extend(annos)

    flush_current()
    logger.info(
        'CP4F proposal stats: %s', json.dumps(proposals.stats)
    )

    segment_predictions = load_all_predictions(args.pred_dir, ordered_segments, counts)
    det_annos = assemble_det_annos(dataset, segment_predictions)
    target_metrics = calculate_injection_metrics(
        dataset, args.dataset, segment_predictions
    )
    print_injection_summary(target_metrics)

    # CVPR: Waymo metrics only where the library exists (PACE: yes; e.g. ARM Delta: no). Otherwise
    # keep the per-segment predictions + ASR and stop before summary.pkl, so a rerun resumes.
    import importlib.util as _ilu
    if os.environ.get('ATLAS_SKIP_WAYMO') == '1' or _ilu.find_spec('waymo_open_dataset') is None:
        _asr = {k: v for k, v in target_metrics.items() if not isinstance(v, np.ndarray) and k != 'fp_records'}
        atomic_json_dump({'status': 'predictions_and_asr_only', 'target_metrics': _asr},
                         str(Path(args.metrics_json).with_name('asr_only.json')))
        print('Waymo metrics unavailable: predictions + asr_only.json saved; rerun to finish the metrics')
        return
    print('\n===== FULL WAYMO EVALUATION =====')
    result_str, result_dict = dataset.evaluation(
        det_annos,
        detector_class_names,
        eval_metric=eval_metric,
    )
    print(result_str)
    print('\n===== WAYMO RESULT DICT =====')
    print(json.dumps(result_dict, indent=2, sort_keys=True, default=json_default))

    l2_summary = compute_l2_map_maph(result_dict, detector_class_names)
    print_l2_summary(l2_summary)

    recall_summary = compute_recall_summary(segment_predictions, cfg_recall_thresh)
    print('\n===== RECALL (all GT boxes, ATLAS frames) =====')
    for k, v in recall_summary.items():
        print(f'{k}: {v}')

    output = {
        'detector': f'PTT-{args.history}',
        'attack_type': 'point_injection',
        'history': int(args.history),
        'dataset_dir': str(Path(args.dataset).resolve()),
        'annos_dir': str(Path(args.annos_dir).resolve()),
        'cp4f_cfg': str(Path(args.cp_cfg).resolve()),
        'cp4f_ckpt': str(Path(args.cp_ckpt).resolve()),
        'ptt_cfg': str(Path(args.cfg_file).resolve()),
        'ptt_ckpt': str(Path(args.ckpt).resolve()),
        'proposal_seed_dir': args.seed_pred_dir or None,
        'data_path': args.data_path,
        'cp4f_proposal_stats': dict(proposals.stats),
        'num_segments': len(ordered_segments),
        'num_frames': len(dataset),
        'target_metrics': target_metrics,
        'waymo_metrics': result_dict,
        'l2_summary': l2_summary,
        'recall': recall_summary,
    }
    json_output = {
        key: value for key, value in output.items()
        if key != 'target_metrics'
    }
    json_output['target_metrics'] = {
        key: value for key, value in target_metrics.items()
        if key not in (
            'fp_scores_vehicle', 'fp_scores_pedestrian',
            'fp_scores_cyclist', 'spoof_best_ious', 'fp_records',
        )
    }
    atomic_json_dump(json_output, args.metrics_json)
    atomic_pickle_dump(output, args.summary_pkl)
    print(f'\nSaved metrics JSON: {args.metrics_json}')
    print(f'Saved complete summary pickle: {args.summary_pkl}')


if __name__ == '__main__':
    main()
PY

DATASET_DIR="$GENERATION_ROOT/$RUN_NAME/dataset"
ANNOS_DIR="$GENERATION_ROOT/$RUN_NAME/annos"

echo "Running ${#CHECKPOINTS[@]} PTT-${HISTORY} checkpoints sequentially on $RUN_NAME."
for ENTRY in "${CHECKPOINTS[@]}"; do
    IFS='|' read -r LABEL PTT_CFG PTT_CKPT CP_CKPT SEED_LABEL <<< "$ENTRY"
    RESULT_DIR="$GENERATION_ROOT/$RUN_NAME/evaluation/ptt${HISTORY}_atlas/$LABEL"
    PRED_DIR="$RESULT_DIR/predictions"
    PROPOSAL_CACHE_DIR="$GENERATION_ROOT/$RUN_NAME/evaluation/ptt${HISTORY}_atlas/cp4f_proposals/${SEED_LABEL:-$LABEL}"
    SEED_DIR=""
    [[ -n "$SEED_LABEL" ]] && SEED_DIR="$GENERATION_ROOT/$RUN_NAME/evaluation/cp4f_atlas/$SEED_LABEL/predictions"

    if [[ "$RESUME" == "1" && -f "$RESULT_DIR/summary.pkl" ]]; then
        echo "Skipping $LABEL: $RESULT_DIR/summary.pkl exists"
        continue
    fi
    FULLVAL_PKL="${FULLVAL[$SEED_LABEL]:-}"
    for path in "$DATASET_DIR" "$ANNOS_DIR" "$DATA_PATH" "$PTT_CFG" "$PTT_CKPT" "$CP_CFG" "$CP_CKPT" "$SEED_DIR" "$FULLVAL_PKL"; do
        [[ -e "$path" ]] || { echo "ERROR: required path does not exist: $path" >&2; exit 1; }
    done
    mkdir -p "$PRED_DIR" "$PROPOSAL_CACHE_DIR"

    echo "==================================================================="
    echo "PTT-${HISTORY} [$LABEL] on $RUN_NAME"
    echo "  PTT  : $PTT_CFG"
    echo "         $PTT_CKPT"
    echo "  CP4F : $CP_CKPT"
    echo "  seed : ${SEED_DIR:-<recompute>}"
    echo "  out  : $RESULT_DIR"
    echo "==================================================================="

    srun -u python "$TMP_PY" \
        --dataset "$DATASET_DIR" \
        --annos_dir "$ANNOS_DIR" \
        --cfg_file "$PTT_CFG" \
        --ckpt "$PTT_CKPT" \
        --cp_cfg "$CP_CFG" \
        --cp_ckpt "$CP_CKPT" \
        --pred_dir "$PRED_DIR" \
        --metrics_json "$RESULT_DIR/metrics.json" \
        --summary_pkl "$RESULT_DIR/summary.pkl" \
        --proposal_cache_dir "$PROPOSAL_CACHE_DIR" \
        --data_path "$DATA_PATH" \
        --seed_pred_dir "$SEED_DIR" \
        --fullval_pkl "$FULLVAL_PKL" \
        --verify_segments "$VERIFY_SEGMENTS" \
        --workers "$WORKERS" \
        --resume "$RESUME" \
        --history "$HISTORY"

    echo "Completed PTT-${HISTORY} [$LABEL]"
done

echo "PTT-${HISTORY} [$FAMILY] on $RUN_NAME done; build tables with: python $PROJECT_ROOT/neurips/abl_tables.py"
